import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine();
        char startChar = line.charAt(0);
        String body = line.substring(1).replace("dot", ".");
        String fullStr = startChar + body;
        if (fullStr.charAt(fullStr.length() - 1) == '.') {
            fullStr = fullStr.substring(0, fullStr.length() - 1) + "dot";
        }
        startChar = fullStr.charAt(0);
        String bodyPart = fullStr.substring(1).replaceFirst("at", "@");
        if (bodyPart.endsWith("@")) {
            bodyPart = bodyPart.substring(0, bodyPart.length() - 1) + "at";
        }
        System.out.println(startChar + bodyPart);
    }
}
